      "CommunityGroupCreateRequest": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "name"
        ],
        "properties": {
          "name": {
            "type": "string",
            "minLength": 1,
            "maxLength": 120
          },
          "description": {
            "type": "string",
            "maxLength": 1000
          },
          "type": {
            "$ref": "#/components/schemas/CommunityGroupType"
          },
          "clubId": {
            "type": "string",
            "minLength": 1
          },
          "squadId": {
            "type": "string",
            "minLength": 1
          },
          "isPublic": {
            "type": "boolean"
          },
          "memberIds": {
            "type": "array",
            "maxItems": 200,
            "items": {
              "type": "string",
              "minLength": 1
            }
          },
          "idempotencyKey": {
            "type": "string",
            "minLength": 8,
            "maxLength": 120
          }
        },
        "allOf": [
          {
            "if": {
              "required": [
                "type"
              ],
              "properties": {
                "type": {
                  "const": "CLUB"
                }
              }
            },
            "then": {
              "required": [
                "clubId"
              ]
            }
          },
          {
            "if": {
              "required": [
                "type"
              ],
              "properties": {
                "type": {
                  "const": "GENERAL"
                }
              }
            },
            "then": {
              "not": {
                "required": [
                  "clubId"
                ]
              }
            }
          },
          {
            "if": {
              "required": [
                "type"
              ],
              "properties": {
                "type": {
                  "const": "SQUAD"
                }
              }
            },
            "then": {
              "required": [
                "squadId"
              ],
              "not": {
                "required": [
                  "isPublic"
                ],
                "properties": {
                  "isPublic": {
                    "const": true
                  }
                }
              }
            }
          },
          {
            "if": {
              "required": [
                "squadId"
              ]
            },
            "then": {
              "properties": {
                "type": {
                  "const": "SQUAD"
                }
              }
            }
          }
        ]
      },
